select (m.ordinality-1)::int,(q.ordinality-1)::int,q.value->'options' into strict mi,qi,current_options from jsonb_array_elements(ex) with ordinality m,jsonb_array_elements(m.value->'questions') with ordinality q where m.value->>'id'=change->>'mode' and q.value->>'number'=change->>'number';
if current_options <> change->'old' then raise exception 'Concurrent content change: %',song.slug;end if;
ex:=jsonb_set(ex,array[mi::text,'questions',qi::text,'options'],change->'new');
if change->'zh' <> 'null'::jsonb then ex:=jsonb_set(ex,array[mi::text,'questions',qi::text,'optionsZh'],change->'zh');end if;
end loop;
update public.song_appreciation_songs set exercises=ex,updated_at=now() where id=song.id;
end loop;end $repair$;

create or replace function public.song_route_guard() returns trigger language plpgsql set search_path=public as $$
declare m jsonb; l jsonb; q jsonb; marker text[]; seen int[]; num int; p int; p1 int; p2 int; expected jsonb; actual jsonb;
begin
select jsonb_agg(value->>'lineId' order by ordinality) into expected from jsonb_array_elements(new.translations) with ordinality where not coalesce((value->>'break')::boolean,false);
for m in select value from jsonb_array_elements(new.exercises) loop
-- Legacy lessons without a full flow remain editable; all current published lessons have one.
if jsonb_array_length(coalesce(m->'listeningLines','[]'::jsonb))=0 then continue;end if;
select jsonb_agg(value->>'lineId' order by ordinality) into actual from jsonb_array_elements(m->'listeningLines') with ordinality;
if actual is distinct from expected then raise exception 'Lyric route missing, merged or reordered: % %',new.slug,m->>'id' using errcode='23514';end if;
seen:='{}';p1:=null;p2:=null;
for l in select value from jsonb_array_elements(m->'listeningLines') loop
for marker in select regexp_matches(l->>'prompt','\{\{q:([0-9]+)\}\}','g') loop
num:=marker[1]::int;
select value into q from jsonb_array_elements(m->'questions') where (value->>'number')::int=num;
if q is null or q->>'lineId' is distinct from l->>'lineId' or num=any(seen) then raise exception 'Invalid question occurrence: % % Q%',new.slug,m->>'id',num using errcode='23514';end if;
seen:=array_append(seen,num);
select ordinality::int into p from jsonb_array_elements_text(q->'options') with ordinality where value=q->>'answer';
if p=p1 and p=p2 then raise exception 'Three answer positions in song order: % %',new.slug,m->>'id' using errcode='23514';end if;
p2:=p1;p1:=p;
end loop;end loop;
if cardinality(seen)<>jsonb_array_length(m->'questions') then raise exception 'Question missing from lyric route: %',new.slug using errcode='23514';end if;
end loop;return new;end $$;
create trigger song_route_before_save before insert or update of exercises,translations on public.song_appreciation_songs for each row execute function public.song_route_guard();
